// More glossary terms: banking and bonds, corporate finance and accounting, economy, and further market terms.
// Same structure as glossary-data.js, plus an optional see: [...] of closely related terms (English names), which
// tools/build-seo.js lists first under "Related terms" on the term's page.
GLOSSARY_TERMS.push(
 // Banking and deposits
 { cat: "banking", see: ["Recurring deposit (RD)", "Auto-sweep", "Tax-saving FD", "Premature withdrawal", "TDS", "Deposit insurance (DICGC)"], term: { en: "Fixed deposit (FD)", hi: "फ़िक्स्ड डिपॉज़िट (FD)" }, def: { en: "A lump sum placed with a bank or NBFC for a set period at an interest rate agreed on the day you invest.", hi: "बैंक या NBFC में तय अवधि के लिए रखी एकमुश्त राशि, जिस पर निवेश के दिन तय ब्याज दर मिलती है।" } },
 { cat: "banking", see: ["Fixed deposit (FD)", "Compound interest", "Maturity amount"], term: { en: "Recurring deposit (RD)", hi: "रेकरिंग डिपॉज़िट (RD)" }, def: { en: "A deposit in which you pay a fixed amount every month for a set period and receive it back with interest at maturity.", hi: "ऐसी जमा योजना जिसमें आप तय अवधि तक हर महीने तय राशि जमा करते हैं और परिपक्वता पर ब्याज सहित पाते हैं।" } },
 { cat: "banking", see: ["Fixed deposit (FD)", "Savings account", "Liquidity"], term: { en: "Auto-sweep", hi: "ऑटो-स्वीप" }, def: { en: "A bank facility, also called sweep-in or flexi deposit, that moves balance above a set limit into an FD and pulls it back when the account runs short.", hi: "बैंक सुविधा (स्वीप-इन या फ़्लेक्सी डिपॉज़िट) जो तय सीमा से ऊपर की राशि को FD में डालती है और खाते में कमी होने पर वापस लाती है।" } },
 { cat: "banking", see: ["Fixed deposit (FD)", "TDS"], term: { en: "Tax-saving FD", hi: "टैक्स-सेविंग FD" }, def: { en: "A five-year lock-in bank deposit whose investment can be claimed as a deduction under the old tax regime. The interest is still taxable.", hi: "पाँच साल के लॉक-इन वाली बैंक जमा, जिसकी राशि पर पुराने टैक्स रेजीम में कटौती मिल सकती है। ब्याज पर टैक्स फिर भी लगता है।" } },
 { cat: "banking", term: { en: "Cumulative FD", hi: "क्यूम्युलेटिव FD" }, def: { en: "An FD that adds interest back to the deposit and pays everything at maturity, so the interest itself earns interest.", hi: "ऐसी FD जिसमें ब्याज जमा में जुड़ता रहता है और सब कुछ परिपक्वता पर मिलता है, इसलिए ब्याज पर भी ब्याज मिलता है।" } },
 { cat: "banking", term: { en: "Non-cumulative FD", hi: "नॉन-क्यूम्युलेटिव FD" }, def: { en: "An FD that pays interest out monthly, quarterly or yearly, and returns the original deposit at maturity.", hi: "ऐसी FD जो ब्याज मासिक, तिमाही या सालाना देती है और परिपक्वता पर मूल राशि लौटाती है।" } },
 { cat: "banking", term: { en: "Corporate FD", hi: "कॉर्पोरेट FD" }, def: { en: "A fixed deposit with a company or NBFC rather than a bank. Rates are usually higher, and there is no DICGC deposit insurance.", hi: "बैंक के बजाय कंपनी या NBFC में फ़िक्स्ड डिपॉज़िट। दरें आमतौर पर ज़्यादा होती हैं, पर DICGC जमा बीमा नहीं मिलता।" } },
 { cat: "banking", term: { en: "Premature withdrawal", hi: "समय से पहले निकासी" }, def: { en: "Closing a deposit before maturity. Banks usually pay a lower rate and may charge a penalty; tax-saving FDs do not allow it.", hi: "परिपक्वता से पहले जमा बंद करना। बैंक आमतौर पर कम दर देते हैं और जुर्माना लगा सकते हैं; टैक्स-सेविंग FD में यह संभव नहीं।" } },
 { cat: "banking", term: { en: "Maturity amount", hi: "परिपक्वता राशि" }, def: { en: "What you receive when a deposit, bond or policy ends: the principal plus any accumulated interest or benefit.", hi: "जमा, बॉन्ड या पॉलिसी पूरी होने पर मिलने वाली राशि: मूलधन और जमा हुआ ब्याज या लाभ।" } },
 { cat: "banking", term: { en: "Deposit insurance (DICGC)", hi: "जमा बीमा (DICGC)" }, def: { en: "Cover from an RBI subsidiary that protects bank deposits up to a limit, currently ₹5 lakh per depositor per bank, including interest.", hi: "RBI की सहायक संस्था का कवर जो बैंक जमा को एक सीमा तक सुरक्षित रखता है, अभी प्रति जमाकर्ता प्रति बैंक ₹5 लाख, ब्याज सहित।" } },
 { cat: "banking", see: ["Current account", "Auto-sweep", "Fixed deposit (FD)"], term: { en: "Savings account", hi: "बचत खाता" }, def: { en: "A bank account for personal money that pays modest interest and allows easy withdrawals.", hi: "निजी पैसे के लिए बैंक खाता, जिस पर सामान्य ब्याज मिलता है और निकासी आसान होती है।" } },
 { cat: "banking", see: ["Savings account", "Overdraft"], term: { en: "Current account", hi: "चालू खाता" }, def: { en: "A bank account for businesses with frequent transactions. It usually pays no interest and can come with an overdraft facility.", hi: "ज़्यादा लेनदेन वाले कारोबार के लिए बैंक खाता। आमतौर पर ब्याज नहीं मिलता और ओवरड्राफ़्ट सुविधा मिल सकती है।" } },
 { cat: "banking", term: { en: "Overdraft", hi: "ओवरड्राफ़्ट" }, def: { en: "A bank limit that lets you withdraw more than your balance. Interest is charged only on the amount used, for the days it is used.", hi: "बैंक सीमा जिससे आप शेष राशि से ज़्यादा निकाल सकते हैं। ब्याज केवल इस्तेमाल की गई राशि और दिनों पर लगता है।" } },
 { cat: "banking", term: { en: "Cash credit", hi: "कैश क्रेडिट" }, def: { en: "A short-term business loan limit, usually secured against stock and receivables, used to fund day-to-day working capital.", hi: "अल्पकालिक कारोबारी लोन सीमा, आमतौर पर स्टॉक और देनदारों की ज़मानत पर, जो रोज़ की वर्किंग कैपिटल के लिए होती है।" } },
 { cat: "banking", term: { en: "NRE and NRO accounts", hi: "NRE और NRO खाते" }, def: { en: "Indian bank accounts for non-residents. NRE holds foreign earnings and its interest is tax-free in India; NRO holds income earned in India.", hi: "अनिवासियों के लिए भारतीय बैंक खाते। NRE में विदेशी कमाई रहती है और ब्याज भारत में करमुक्त है; NRO में भारत में हुई आय रहती है।" } },
 { cat: "banking", term: { en: "FCNR deposit", hi: "FCNR डिपॉज़िट" }, def: { en: "A fixed deposit for non-residents held in a foreign currency, which protects the depositor from rupee exchange-rate movements.", hi: "अनिवासियों के लिए विदेशी मुद्रा में फ़िक्स्ड डिपॉज़िट, जो जमाकर्ता को रुपये की विनिमय दर के उतार-चढ़ाव से बचाती है।" } },
 { cat: "banking", term: { en: "IFSC code", hi: "IFSC कोड" }, def: { en: "An 11-character code that identifies a bank branch for electronic transfers such as NEFT, RTGS and IMPS.", hi: "11 अक्षरों का कोड जो NEFT, RTGS और IMPS जैसे इलेक्ट्रॉनिक ट्रांसफ़र के लिए बैंक शाखा की पहचान करता है।" } },
 { cat: "banking", term: { en: "UPI", hi: "UPI" }, def: { en: "Unified Payments Interface: India's instant mobile payment system, which moves money between bank accounts through an app.", hi: "यूनिफ़ाइड पेमेंट्स इंटरफ़ेस: भारत की तुरंत मोबाइल भुगतान प्रणाली, जो ऐप से बैंक खातों के बीच पैसा भेजती है।" } },
 { cat: "banking", term: { en: "Commercial bank", hi: "वाणिज्यिक बैंक" }, def: { en: "A bank that takes deposits from the public and lends to people and businesses, regulated in India by the RBI.", hi: "ऐसा बैंक जो जनता से जमा लेता है और लोगों व कारोबार को कर्ज़ देता है; भारत में इसे RBI नियंत्रित करता है।" } },
 { cat: "banking", term: { en: "NBFC", hi: "NBFC" }, def: { en: "Non-Banking Financial Company: a company that lends or invests but cannot accept demand deposits or issue cheques drawn on itself.", hi: "नॉन-बैंकिंग फ़ाइनेंशियल कंपनी: कर्ज़ या निवेश का काम करने वाली कंपनी, जो मांग जमा नहीं ले सकती और अपने ऊपर चेक जारी नहीं कर सकती।" } },
 { cat: "banking", term: { en: "NABARD", hi: "नाबार्ड (NABARD)" }, def: { en: "National Bank for Agriculture and Rural Development: the development bank that funds and supports agriculture and rural credit in India.", hi: "राष्ट्रीय कृषि और ग्रामीण विकास बैंक: भारत में कृषि और ग्रामीण ऋण को धन और सहायता देने वाला विकास बैंक।" } },
 { cat: "banking", term: { en: "NPA (non-performing asset)", hi: "NPA (अनर्जक आस्ति)" }, def: { en: "A loan on which interest or principal has been overdue for a set period, generally more than 90 days. High NPAs hurt a bank's profits.", hi: "ऐसा लोन जिसका ब्याज या मूलधन तय अवधि, आमतौर पर 90 दिन से ज़्यादा, से बकाया हो। ज़्यादा NPA बैंक का मुनाफ़ा घटाते हैं।" } },
 { cat: "banking", term: { en: "TDS", hi: "TDS (स्रोत पर कर कटौती)" }, def: { en: "Tax Deducted at Source: tax taken out by the payer, such as a bank on FD interest, before paying you. You can claim it when filing your return.", hi: "स्रोत पर कर कटौती: भुगतान से पहले देने वाले द्वारा काटा गया टैक्स, जैसे FD ब्याज पर बैंक। रिटर्न भरते समय इसका दावा कर सकते हैं।" } },
 { cat: "banking", see: ["Compound interest", "Interest rate"], term: { en: "Simple interest", hi: "साधारण ब्याज" }, def: { en: "Interest worked out only on the original principal: principal × rate × time.", hi: "केवल मूल राशि पर निकाला गया ब्याज: मूलधन × दर × समय।" } },
 { cat: "banking", see: ["Simple interest", "Compounding", "Future value"], term: { en: "Compound interest", hi: "चक्रवृद्धि ब्याज" }, def: { en: "Interest worked out on the principal plus interest already earned, so growth speeds up over time.", hi: "मूलधन और पहले मिले ब्याज, दोनों पर निकाला गया ब्याज, इसलिए समय के साथ बढ़त तेज़ होती है।" } },
 { cat: "banking", term: { en: "Interest rate", hi: "ब्याज दर" }, def: { en: "The price of money: what a borrower pays or a saver earns, usually stated as a percentage per year.", hi: "पैसे की कीमत: उधार लेने वाला जो देता है या बचत करने वाला जो पाता है, आमतौर पर प्रति वर्ष प्रतिशत में।" } },
 { cat: "banking", term: { en: "Floating interest rate", hi: "फ़्लोटिंग ब्याज दर" }, def: { en: "A rate that moves with a benchmark such as the repo rate, so a loan's cost or EMI can change during its term.", hi: "रेपो रेट जैसे बेंचमार्क के साथ बदलने वाली दर, इसलिए लोन की लागत या EMI अवधि के बीच बदल सकती है।" } },
 { cat: "banking", term: { en: "Secured loan", hi: "सिक्योर्ड लोन" }, def: { en: "A loan backed by an asset such as a house, car or gold, which the lender can sell if you default. Rates are usually lower.", hi: "घर, कार या सोने जैसी संपत्ति की ज़मानत वाला लोन, जिसे चूक होने पर कर्ज़दाता बेच सकता है। दरें आमतौर पर कम होती हैं।" } },
 { cat: "banking", term: { en: "Unsecured loan", hi: "अनसिक्योर्ड लोन" }, def: { en: "A loan with no asset pledged, such as a personal loan or credit card balance. Rates are usually higher.", hi: "बिना संपत्ति गिरवी का लोन, जैसे पर्सनल लोन या क्रेडिट कार्ड बकाया। दरें आमतौर पर ज़्यादा होती हैं।" } },
 { cat: "banking", term: { en: "Collateral", hi: "कोलैटरल (ज़मानत)" }, def: { en: "An asset pledged to a lender as security for a loan, which the lender can claim if the loan is not repaid.", hi: "लोन की सुरक्षा के लिए कर्ज़दाता के पास गिरवी रखी संपत्ति, जिसे लोन न चुकाने पर वह ले सकता है।" } },
 { cat: "banking", term: { en: "Guarantor", hi: "गारंटर" }, def: { en: "A person who promises to repay a loan if the borrower fails to, and who becomes liable in that case.", hi: "वह व्यक्ति जो वादा करता है कि कर्ज़दार न चुका सके तो वह चुकाएगा, और तब वही ज़िम्मेदार होता है।" } },
 { cat: "banking", term: { en: "Home loan", hi: "होम लोन" }, def: { en: "A long-term loan to buy or build a home, secured against the property and repaid through EMIs.", hi: "घर ख़रीदने या बनाने के लिए लंबी अवधि का लोन, जिसकी ज़मानत वही संपत्ति होती है और जो EMI से चुकाया जाता है।" } },
 { cat: "banking", term: { en: "Moratorium period", hi: "मोरेटोरियम अवधि" }, def: { en: "A set time during which a borrower need not repay, as with education loans during study. Interest may still build up.", hi: "तय समय जिसमें कर्ज़दार को चुकाना नहीं पड़ता, जैसे पढ़ाई के दौरान शिक्षा लोन। ब्याज फिर भी जुड़ सकता है।" } },
 { cat: "banking", see: ["Coupon rate", "Yield to maturity (YTM)", "Debenture", "Government securities (G-Sec)"], term: { en: "Bond", hi: "बॉन्ड" }, def: { en: "A loan you give to a government or company. It pays regular interest (the coupon) and returns the face value at maturity.", hi: "सरकार या कंपनी को दिया गया कर्ज़। इस पर नियमित ब्याज (कूपन) मिलता है और परिपक्वता पर अंकित मूल्य वापस मिलता है।" } },
 { cat: "banking", see: ["Bond", "Convertible bond"], term: { en: "Debenture", hi: "डिबेंचर" }, def: { en: "A company's debt instrument, which may be secured or unsecured, and which pays a fixed rate of interest.", hi: "कंपनी का ऋण साधन, जो सुरक्षित या असुरक्षित हो सकता है और जिस पर तय दर से ब्याज मिलता है।" } },
 { cat: "banking", term: { en: "Coupon rate", hi: "कूपन दर" }, def: { en: "The yearly interest a bond pays, as a percentage of its face value. It usually stays fixed for the bond's life.", hi: "बॉन्ड का सालाना ब्याज, उसके अंकित मूल्य के प्रतिशत के रूप में। यह आमतौर पर पूरी अवधि तय रहता है।" } },
 { cat: "banking", see: ["Bond", "Coupon rate", "Yield curve"], term: { en: "Yield to maturity (YTM)", hi: "यील्ड टू मैच्योरिटी (YTM)" }, def: { en: "The total yearly return you earn if you buy a bond at today's price and hold it to maturity. Price and yield move in opposite directions.", hi: "आज की कीमत पर बॉन्ड ख़रीदकर परिपक्वता तक रखने पर मिलने वाला कुल सालाना रिटर्न। कीमत और यील्ड उलटी दिशा में चलते हैं।" } },
 { cat: "banking", term: { en: "Yield curve", hi: "यील्ड कर्व" }, def: { en: "A chart of bond yields against time to maturity. An inverted curve, where short rates exceed long rates, is watched as a warning of slowdown.", hi: "बॉन्ड यील्ड और परिपक्वता अवधि का चार्ट। उलटा कर्व, जहाँ छोटी अवधि की दर लंबी से ज़्यादा हो, मंदी की चेतावनी माना जाता है।" } },
 { cat: "banking", term: { en: "Government securities (G-Sec)", hi: "सरकारी प्रतिभूतियाँ (G-Sec)" }, def: { en: "Bonds and bills issued by the central or state governments. They are treated as having almost no default risk.", hi: "केंद्र या राज्य सरकारों के जारी बॉन्ड और बिल। इनमें डिफ़ॉल्ट का जोखिम लगभग न के बराबर माना जाता है।" } },
 { cat: "banking", term: { en: "Treasury bill (T-bill)", hi: "ट्रेज़री बिल (T-bill)" }, def: { en: "A short-term central government security of up to one year, issued at a discount and redeemed at face value.", hi: "एक साल तक की केंद्र सरकार की अल्पकालिक प्रतिभूति, जो छूट पर जारी होकर अंकित मूल्य पर भुनाई जाती है।" } },
 { cat: "banking", term: { en: "Commercial paper", hi: "कमर्शियल पेपर" }, def: { en: "An unsecured short-term note issued by highly rated companies to borrow money for up to one year.", hi: "उच्च रेटिंग वाली कंपनियों का बिना ज़मानत अल्पकालिक नोट, जिससे वे एक साल तक के लिए उधार लेती हैं।" } },
 { cat: "banking", term: { en: "Certificate of deposit", hi: "सर्टिफ़िकेट ऑफ़ डिपॉज़िट" }, def: { en: "A tradable short-term deposit instrument issued by banks and financial institutions, mainly to larger investors.", hi: "बैंकों और वित्तीय संस्थानों का ट्रेड योग्य अल्पकालिक जमा साधन, मुख्यतः बड़े निवेशकों के लिए।" } },
 { cat: "banking", term: { en: "Convertible bond", hi: "कन्वर्टिबल बॉन्ड" }, def: { en: "A bond the holder can exchange for a set number of the company's shares, usually paying a lower coupon in return.", hi: "ऐसा बॉन्ड जिसे धारक कंपनी के तय शेयरों में बदल सकता है, और बदले में कूपन आमतौर पर कम होता है।" } },
 { cat: "banking", term: { en: "Junk bond", hi: "जंक बॉन्ड" }, def: { en: "A bond rated below investment grade. It pays a high yield because the risk of default is high.", hi: "निवेश ग्रेड से नीचे रेटिंग वाला बॉन्ड। डिफ़ॉल्ट का जोखिम ज़्यादा होने से इसकी यील्ड ऊँची होती है।" } },
 { cat: "banking", term: { en: "Green bond", hi: "ग्रीन बॉन्ड" }, def: { en: "A bond whose money is committed to environmental projects such as renewable energy or clean transport.", hi: "ऐसा बॉन्ड जिसका पैसा नवीकरणीय ऊर्जा या स्वच्छ परिवहन जैसी पर्यावरण परियोजनाओं के लिए तय होता है।" } },
 { cat: "banking", term: { en: "Credit rating", hi: "क्रेडिट रेटिंग" }, def: { en: "An opinion from an agency such as CRISIL, ICRA or CARE on how likely a borrower is to repay. AAA is the highest grade.", hi: "CRISIL, ICRA या CARE जैसी एजेंसी की राय कि कर्ज़दार के चुकाने की कितनी संभावना है। AAA सबसे ऊँची श्रेणी है।" } },
 { cat: "banking", term: { en: "Basis point", hi: "बेसिस पॉइंट" }, def: { en: "One hundredth of one percent (0.01%). A rate rising from 6.50% to 6.75% has risen by 25 basis points.", hi: "एक प्रतिशत का सौवाँ हिस्सा (0.01%)। दर 6.50% से 6.75% होने का मतलब 25 बेसिस पॉइंट की बढ़त।" } },
 { cat: "banking", term: { en: "Money market", hi: "मुद्रा बाज़ार" }, def: { en: "The market for borrowing and lending for up to one year, through instruments such as T-bills, commercial paper and certificates of deposit.", hi: "एक साल तक के उधार-लेनदेन का बाज़ार, जिसमें T-bill, कमर्शियल पेपर और सर्टिफ़िकेट ऑफ़ डिपॉज़िट जैसे साधन होते हैं।" } },
 { cat: "banking", term: { en: "Capital market", hi: "पूँजी बाज़ार" }, def: { en: "The market for long-term finance of more than one year, including shares and bonds. It has primary and secondary segments.", hi: "एक साल से लंबी अवधि के धन का बाज़ार, जिसमें शेयर और बॉन्ड आते हैं। इसके प्राथमिक और द्वितीयक हिस्से होते हैं।" } },
 { cat: "banking", term: { en: "Bond market", hi: "बॉन्ड बाज़ार" }, def: { en: "The market in which governments and companies issue bonds and investors trade them.", hi: "वह बाज़ार जहाँ सरकारें और कंपनियाँ बॉन्ड जारी करती हैं और निवेशक उनका लेनदेन करते हैं।" } },
 { cat: "banking", term: { en: "Insurance premium", hi: "बीमा प्रीमियम" }, def: { en: "The amount you pay an insurer, usually yearly or monthly, to keep a policy in force.", hi: "पॉलिसी चालू रखने के लिए बीमा कंपनी को दी जाने वाली राशि, आमतौर पर सालाना या मासिक।" } },
 { cat: "banking", term: { en: "Annuity", hi: "एन्युटी" }, def: { en: "A series of equal payments at regular intervals, or a product that pays you a regular income in return for a lump sum.", hi: "नियमित अंतराल पर बराबर भुगतान की श्रृंखला, या ऐसा उत्पाद जो एकमुश्त राशि के बदले नियमित आय देता है।" } },
 { cat: "banking", term: { en: "Endowment policy", hi: "एंडोमेंट पॉलिसी" }, def: { en: "Life insurance that pays on death or at maturity. Returns are often low, and the cover is small for the premium paid.", hi: "जीवन बीमा जो मृत्यु या परिपक्वता पर भुगतान करता है। रिटर्न अक्सर कम होता है और प्रीमियम के मुकाबले कवर छोटा।" } },
 { cat: "banking", term: { en: "Amortisation", hi: "परिशोधन (Amortisation)" }, def: { en: "Paying off a loan through scheduled instalments. In accounting, spreading the cost of an intangible asset over its useful life.", hi: "तय किस्तों से लोन चुकाना। लेखांकन में, अमूर्त संपत्ति की लागत को उसके उपयोगी जीवन में बाँटना।" } },

 // Corporate finance and accounting
 { cat: "corporate", see: ["Balance sheet", "Fixed asset", "Current assets", "Intangible asset"], term: { en: "Asset", hi: "एसेट (संपत्ति)" }, def: { en: "Something a person or company owns or controls that is expected to bring future benefit, such as cash, stock or machinery.", hi: "व्यक्ति या कंपनी के स्वामित्व या नियंत्रण की चीज़ जिससे भविष्य में लाभ की उम्मीद हो, जैसे नकद, स्टॉक या मशीनरी।" } },
 { cat: "corporate", see: ["Balance sheet", "Current liabilities", "Asset"], term: { en: "Liability", hi: "देनदारी (Liability)" }, def: { en: "Something a person or company owes to others, such as loans, payables or taxes due.", hi: "व्यक्ति या कंपनी का दूसरों के प्रति बकाया, जैसे लोन, देय राशि या बकाया टैक्स।" } },
 { cat: "corporate", term: { en: "Current assets", hi: "चालू संपत्तियाँ" }, def: { en: "Assets expected to turn into cash within a year, such as inventory, receivables and bank balances.", hi: "एक साल में नकद में बदलने वाली संपत्तियाँ, जैसे इन्वेंटरी, देनदार और बैंक शेष।" } },
 { cat: "corporate", term: { en: "Current liabilities", hi: "चालू देनदारियाँ" }, def: { en: "Amounts due within a year, such as trade payables, short-term loans and taxes payable.", hi: "एक साल में चुकानी होने वाली राशियाँ, जैसे व्यापार देय, अल्पकालिक लोन और देय टैक्स।" } },
 { cat: "corporate", see: ["Depreciation", "Capital expenditure (capex)"], term: { en: "Fixed asset", hi: "स्थायी संपत्ति (Fixed asset)" }, def: { en: "A long-term asset used in the business rather than for sale, such as land, buildings or machinery.", hi: "बिक्री के बजाय कारोबार में काम आने वाली दीर्घकालिक संपत्ति, जैसे ज़मीन, भवन या मशीनरी।" } },
 { cat: "corporate", term: { en: "Intangible asset", hi: "अमूर्त संपत्ति" }, def: { en: "A valuable asset with no physical form, such as a patent, brand, software or goodwill.", hi: "बिना भौतिक रूप की मूल्यवान संपत्ति, जैसे पेटेंट, ब्रांड, सॉफ़्टवेयर या गुडविल।" } },
 { cat: "corporate", see: ["Fixed asset", "Amortisation", "EBITDA"], term: { en: "Depreciation", hi: "मूल्यह्रास (Depreciation)" }, def: { en: "Spreading the cost of a fixed asset over its useful life as an expense. It reduces profit but involves no cash outflow.", hi: "स्थायी संपत्ति की लागत को उसके उपयोगी जीवन में खर्च के रूप में बाँटना। इससे मुनाफ़ा घटता है पर नकद बाहर नहीं जाता।" } },
 { cat: "corporate", see: ["Current assets", "Working capital"], term: { en: "Inventory", hi: "इन्वेंटरी (स्टॉक)" }, def: { en: "Raw materials, work in progress and finished goods that a business holds for making or selling.", hi: "कच्चा माल, अधूरा माल और तैयार माल जो कारोबार बनाने या बेचने के लिए रखता है।" } },
 { cat: "corporate", term: { en: "Receivables", hi: "प्राप्य राशि (Receivables)" }, def: { en: "Money customers owe a business for goods or services already supplied on credit. Also called debtors.", hi: "उधार पर दिए गए माल या सेवाओं के लिए ग्राहकों पर बकाया राशि। इन्हें देनदार भी कहते हैं।" } },
 { cat: "corporate", term: { en: "Payables", hi: "देय राशि (Payables)" }, def: { en: "Money a business owes its suppliers for goods or services received on credit. Also called creditors.", hi: "उधार पर मिले माल या सेवाओं के लिए कारोबार का आपूर्तिकर्ताओं को देय। इन्हें लेनदार भी कहते हैं।" } },
 { cat: "corporate", see: ["Net profit", "Operating margin", "Revenue (sales)"], term: { en: "Gross profit", hi: "सकल लाभ (Gross profit)" }, def: { en: "Revenue minus the direct cost of goods sold, before other expenses.", hi: "राजस्व में से बेचे गए माल की प्रत्यक्ष लागत घटाने पर मिला लाभ, अन्य खर्चों से पहले।" } },
 { cat: "corporate", term: { en: "EBIT", hi: "EBIT" }, def: { en: "Earnings before interest and tax: profit from operations before finance costs and tax.", hi: "ब्याज और टैक्स से पहले की कमाई: वित्त लागत और टैक्स से पहले का परिचालन लाभ।" } },
 { cat: "corporate", term: { en: "PAT (profit after tax)", hi: "PAT (कर बाद लाभ)" }, def: { en: "Profit left after all expenses, interest and tax. It is the same as net profit and belongs to the shareholders.", hi: "सभी खर्च, ब्याज और टैक्स के बाद बचा लाभ। यह शुद्ध लाभ ही है और शेयरधारकों का होता है।" } },
 { cat: "corporate", term: { en: "Cost of goods sold (COGS)", hi: "बेचे गए माल की लागत (COGS)" }, def: { en: "The direct cost of making or buying the goods sold in a period, such as materials and factory labour.", hi: "किसी अवधि में बेचे गए माल को बनाने या ख़रीदने की प्रत्यक्ष लागत, जैसे सामग्री और फ़ैक्टरी मज़दूरी।" } },
 { cat: "corporate", term: { en: "Ledger", hi: "लेजर (खाता बही)" }, def: { en: "The book or system where a business's transactions are posted account by account. The general ledger feeds the financial statements.", hi: "वह बही या प्रणाली जहाँ कारोबार के लेनदेन खाते-वार दर्ज होते हैं। जनरल लेजर से वित्तीय विवरण बनते हैं।" } },
 { cat: "corporate", term: { en: "Journal entry", hi: "जर्नल एंट्री" }, def: { en: "The first record of a transaction in double-entry bookkeeping, showing the account debited and the account credited.", hi: "दोहरी प्रविष्टि में लेनदेन का पहला रिकॉर्ड, जिसमें डेबिट और क्रेडिट होने वाले खाते दिखते हैं।" } },
 { cat: "corporate", term: { en: "Trial balance", hi: "ट्रायल बैलेंस" }, def: { en: "A list of all ledger balances at a date, used to check that total debits equal total credits before preparing accounts.", hi: "किसी तारीख़ पर सभी लेजर शेष की सूची, जिससे खाते बनाने से पहले जाँचा जाता है कि कुल डेबिट और क्रेडिट बराबर हैं।" } },
 { cat: "corporate", term: { en: "Invoice", hi: "इनवॉइस (बीजक)" }, def: { en: "A bill from a seller showing the goods or services supplied, the amount due and the payment terms.", hi: "विक्रेता का बिल, जिसमें दिया गया माल या सेवा, बकाया राशि और भुगतान की शर्तें होती हैं।" } },
 { cat: "corporate", see: ["Discounted cash flow (DCF)", "Internal rate of return (IRR)", "Present value"], term: { en: "Net present value (NPV)", hi: "शुद्ध वर्तमान मूल्य (NPV)" }, def: { en: "The present value of a project's future cash flows minus its cost. A positive NPV means the project earns more than the required return.", hi: "परियोजना के भविष्य के कैश फ़्लो का वर्तमान मूल्य घटा उसकी लागत। सकारात्मक NPV का मतलब आवश्यक रिटर्न से ज़्यादा कमाई।" } },
 { cat: "corporate", see: ["Net present value (NPV)", "Hurdle rate"], term: { en: "Internal rate of return (IRR)", hi: "आंतरिक प्रतिफल दर (IRR)" }, def: { en: "The discount rate at which a project's NPV is zero. Projects are usually accepted when IRR is above the required return.", hi: "वह छूट दर जिस पर परियोजना का NPV शून्य हो। IRR आवश्यक रिटर्न से ऊपर होने पर परियोजना आमतौर पर स्वीकार होती है।" } },
 { cat: "corporate", term: { en: "Payback period", hi: "पेबैक अवधि" }, def: { en: "The time a project takes to recover its initial cost from its cash flows. Simple, but it ignores later cash flows and the time value of money.", hi: "परियोजना को कैश फ़्लो से अपनी शुरुआती लागत वसूलने में लगने वाला समय। सरल है, पर बाद के कैश फ़्लो और धन के समय मूल्य को नहीं देखता।" } },
 { cat: "corporate", term: { en: "Hurdle rate", hi: "हर्डल रेट" }, def: { en: "The minimum return a company requires before it accepts a project, often based on its cost of capital.", hi: "परियोजना स्वीकार करने के लिए कंपनी का न्यूनतम आवश्यक रिटर्न, अक्सर पूँजी की लागत पर आधारित।" } },
 { cat: "corporate", see: ["Future value", "Net present value (NPV)"], term: { en: "Present value", hi: "वर्तमान मूल्य (Present value)" }, def: { en: "What a future amount is worth today, after discounting at a chosen rate of return.", hi: "भविष्य की राशि का आज का मूल्य, चुनी हुई रिटर्न दर से छूट देने के बाद।" } },
 { cat: "corporate", see: ["Present value", "Compound interest"], term: { en: "Future value", hi: "भविष्य मूल्य (Future value)" }, def: { en: "What an amount invested today will grow to at a given rate of return over a given time.", hi: "आज निवेश की गई राशि दी गई रिटर्न दर और समय में कितनी हो जाएगी।" } },
 { cat: "corporate", see: ["Cost of equity", "CAPM"], term: { en: "Cost of capital (WACC)", hi: "पूँजी की लागत (WACC)" }, def: { en: "The average return a company must pay its lenders and shareholders, weighted by how much of each kind of finance it uses.", hi: "वह औसत रिटर्न जो कंपनी को कर्ज़दाताओं और शेयरधारकों को देना होता है, हर प्रकार के धन के अनुपात से भारित।" } },
 { cat: "corporate", term: { en: "Cost of equity", hi: "इक्विटी की लागत" }, def: { en: "The return shareholders expect for the risk of owning a company's shares, often estimated with CAPM.", hi: "कंपनी के शेयर रखने के जोखिम के बदले शेयरधारकों का अपेक्षित रिटर्न, जिसका अनुमान अक्सर CAPM से लगाया जाता है।" } },
 { cat: "corporate", term: { en: "Capital structure", hi: "पूँजी संरचना" }, def: { en: "The mix of debt and equity a company uses to finance itself.", hi: "कंपनी के धन जुटाने में कर्ज़ और इक्विटी का मिश्रण।" } },
 { cat: "corporate", term: { en: "Financial leverage", hi: "वित्तीय लीवरेज" }, def: { en: "Using fixed-cost debt to raise returns to shareholders. It magnifies both profits and losses per share.", hi: "शेयरधारकों का रिटर्न बढ़ाने के लिए तय लागत वाले कर्ज़ का उपयोग। यह प्रति शेयर लाभ और घाटा, दोनों बढ़ाता है।" } },
 { cat: "corporate", term: { en: "Operating leverage", hi: "ऑपरेटिंग लीवरेज" }, def: { en: "How strongly operating profit reacts to a change in sales. High fixed costs mean high operating leverage.", hi: "बिक्री में बदलाव पर परिचालन लाभ कितना बदलता है। ज़्यादा स्थायी लागत का मतलब ज़्यादा ऑपरेटिंग लीवरेज।" } },
 { cat: "corporate", term: { en: "Cash conversion cycle", hi: "कैश कन्वर्ज़न साइकिल" }, def: { en: "The days between paying suppliers and collecting cash from customers: inventory days plus receivable days minus payable days.", hi: "आपूर्तिकर्ताओं को भुगतान और ग्राहकों से नकद मिलने के बीच के दिन: इन्वेंटरी दिन + प्राप्य दिन − देय दिन।" } },
 { cat: "corporate", term: { en: "Economic order quantity (EOQ)", hi: "इकोनॉमिक ऑर्डर क्वांटिटी (EOQ)" }, def: { en: "The order size that minimises the total cost of ordering and holding inventory.", hi: "वह ऑर्डर आकार जो ऑर्डर करने और इन्वेंटरी रखने की कुल लागत को न्यूनतम करता है।" } },
 { cat: "corporate", term: { en: "Just-in-time (JIT)", hi: "जस्ट-इन-टाइम (JIT)" }, def: { en: "An inventory approach in which materials arrive only as needed, which cuts holding costs but depends on reliable suppliers.", hi: "इन्वेंटरी का तरीका जिसमें सामग्री तभी आती है जब ज़रूरत हो; इससे रखने की लागत घटती है पर भरोसेमंद आपूर्तिकर्ता चाहिए।" } },
 { cat: "corporate", see: ["ROE (return on equity)", "Ratio analysis"], term: { en: "DuPont analysis", hi: "ड्यूपॉन्ट विश्लेषण" }, def: { en: "Breaking ROE into net margin × asset turnover × equity multiplier to see what drives a company's return.", hi: "ROE को नेट मार्जिन × एसेट टर्नओवर × इक्विटी मल्टीप्लायर में बाँटना, ताकि दिखे कि रिटर्न किससे बन रहा है।" } },
 { cat: "corporate", see: ["Current ratio", "Debt-to-equity", "DuPont analysis"], term: { en: "Ratio analysis", hi: "अनुपात विश्लेषण" }, def: { en: "Comparing figures from financial statements to judge a company's liquidity, solvency, profitability and efficiency.", hi: "वित्तीय विवरण के आँकड़ों की तुलना से कंपनी की तरलता, शोधन क्षमता, लाभप्रदता और दक्षता आँकना।" } },
 { cat: "corporate", term: { en: "ROCE (return on capital employed)", hi: "ROCE (नियोजित पूँजी पर रिटर्न)" }, def: { en: "EBIT divided by capital employed (equity plus long-term debt). It shows how well a company uses all its long-term funds.", hi: "EBIT ÷ नियोजित पूँजी (इक्विटी + दीर्घकालिक कर्ज़)। यह दिखाता है कि कंपनी अपने सभी दीर्घकालिक धन का कितना अच्छा उपयोग करती है।" } },
 { cat: "corporate", term: { en: "Interest coverage ratio", hi: "ब्याज कवरेज अनुपात" }, def: { en: "EBIT divided by interest expense. It shows how comfortably operating profit covers interest payments.", hi: "EBIT ÷ ब्याज खर्च। यह दिखाता है कि परिचालन लाभ ब्याज भुगतान को कितनी आसानी से पूरा करता है।" } },
 { cat: "corporate", term: { en: "Quick ratio", hi: "क्विक अनुपात" }, def: { en: "Current assets minus inventory, divided by current liabilities. A stricter test of short-term liquidity than the current ratio.", hi: "(चालू संपत्ति − इन्वेंटरी) ÷ चालू देनदारी। करंट रेशियो से ज़्यादा कड़ी अल्पकालिक तरलता जाँच।" } },
 { cat: "corporate", term: { en: "Solvency ratio", hi: "सॉल्वेंसी अनुपात" }, def: { en: "A measure of whether a business can meet its long-term obligations, such as debt-to-equity or interest coverage.", hi: "यह मापक कि कारोबार अपनी दीर्घकालिक देनदारियाँ पूरी कर सकता है या नहीं, जैसे डेट-टू-इक्विटी या ब्याज कवरेज।" } },
 { cat: "corporate", term: { en: "Return on investment (ROI)", hi: "निवेश पर रिटर्न (ROI)" }, def: { en: "Gain from an investment divided by its cost, as a percentage. It does not by itself account for how long the money was invested.", hi: "निवेश से लाभ ÷ उसकी लागत, प्रतिशत में। यह अपने आप में नहीं बताता कि पैसा कितने समय लगा रहा।" } },
 { cat: "corporate", term: { en: "Break-even point", hi: "ब्रेक-ईवन बिंदु" }, def: { en: "The sales level at which total revenue equals total cost, so there is neither profit nor loss.", hi: "बिक्री का वह स्तर जहाँ कुल राजस्व और कुल लागत बराबर हों, यानी न लाभ न हानि।" } },
 { cat: "corporate", term: { en: "Economies of scale", hi: "बड़े पैमाने की मितव्ययिता" }, def: { en: "Cost per unit falling as output grows, because fixed costs are spread over more units.", hi: "उत्पादन बढ़ने पर प्रति इकाई लागत का घटना, क्योंकि स्थायी लागत ज़्यादा इकाइयों में बँट जाती है।" } },
 { cat: "corporate", term: { en: "Economic moat", hi: "इकोनॉमिक मोट" }, def: { en: "A lasting advantage, such as brand, scale or switching costs, that protects a company's profits from competitors.", hi: "ब्रांड, पैमाने या स्विचिंग लागत जैसा टिकाऊ लाभ, जो कंपनी के मुनाफ़े को प्रतिस्पर्धियों से बचाता है।" } },
 { cat: "corporate", term: { en: "Intrinsic value", hi: "आंतरिक मूल्य (Intrinsic value)" }, def: { en: "An estimate of what a business or share is truly worth based on its fundamentals, whatever its market price.", hi: "बाज़ार कीमत से अलग, बुनियादी बातों के आधार पर कारोबार या शेयर के असली मूल्य का अनुमान।" } },
 { cat: "corporate", term: { en: "Face value", hi: "अंकित मूल्य (Face value)" }, def: { en: "The stated value of a share or bond in the company's records, such as ₹10 per share. It often differs widely from the market price.", hi: "कंपनी के रिकॉर्ड में शेयर या बॉन्ड का घोषित मूल्य, जैसे ₹10 प्रति शेयर। यह अक्सर बाज़ार कीमत से बहुत अलग होता है।" } },
 { cat: "corporate", term: { en: "Authorised capital", hi: "अधिकृत पूँजी" }, def: { en: "The maximum share capital a company's charter allows it to issue. Issued, subscribed and paid-up capital are parts of it.", hi: "कंपनी के चार्टर के अनुसार जारी की जा सकने वाली अधिकतम शेयर पूँजी। जारी, अभिदत्त और चुकता पूँजी इसके हिस्से हैं।" } },
 { cat: "corporate", term: { en: "Paid-up capital", hi: "चुकता पूँजी" }, def: { en: "The part of a company's share capital that shareholders have actually paid for.", hi: "कंपनी की शेयर पूँजी का वह हिस्सा जिसका भुगतान शेयरधारक वास्तव में कर चुके हैं।" } },
 { cat: "corporate", see: ["Share (stock)", "Dividend"], term: { en: "Preference shares", hi: "प्रेफ़रेंस शेयर" }, def: { en: "Shares that receive a fixed dividend and are repaid before equity holders on winding up, usually with limited voting rights.", hi: "ऐसे शेयर जिन्हें तय डिविडेंड मिलता है और समापन पर इक्विटी से पहले भुगतान होता है; मतदान अधिकार आमतौर पर सीमित।" } },
 { cat: "corporate", term: { en: "Shareholder", hi: "शेयरधारक" }, def: { en: "A person or institution that owns shares in a company and so holds part of its ownership.", hi: "कंपनी के शेयर रखने वाला व्यक्ति या संस्था, जो उसके स्वामित्व में हिस्सेदार होता है।" } },
 { cat: "corporate", term: { en: "Dilution", hi: "डाइल्यूशन" }, def: { en: "The fall in an existing shareholder's percentage ownership when a company issues new shares.", hi: "कंपनी के नए शेयर जारी करने पर मौजूदा शेयरधारक की प्रतिशत हिस्सेदारी का घटना।" } },
 { cat: "corporate", term: { en: "ESOP", hi: "ESOP" }, def: { en: "Employee Stock Option Plan: a company benefit that gives employees the right to buy its shares at a set price after a vesting period.", hi: "एम्प्लॉयी स्टॉक ऑप्शन प्लान: कर्मचारियों को वेस्टिंग अवधि के बाद तय कीमत पर कंपनी के शेयर ख़रीदने का अधिकार।" } },
 { cat: "corporate", see: ["Acquisition", "Amalgamation", "Due diligence"], term: { en: "Merger", hi: "मर्जर (विलय)" }, def: { en: "Two companies combining into one, usually paid for by exchanging shares.", hi: "दो कंपनियों का मिलकर एक होना, जिसका भुगतान आमतौर पर शेयरों की अदला-बदली से होता है।" } },
 { cat: "corporate", term: { en: "Acquisition", hi: "अधिग्रहण (Acquisition)" }, def: { en: "One company buying control of another, with the target usually continuing as a subsidiary or being absorbed.", hi: "एक कंपनी का दूसरी का नियंत्रण ख़रीदना; लक्षित कंपनी आमतौर पर सहायक बनी रहती है या उसी में मिल जाती है।" } },
 { cat: "corporate", term: { en: "Amalgamation", hi: "समामेलन (Amalgamation)" }, def: { en: "Two or more companies combining, either into a new company or into one of the existing ones.", hi: "दो या ज़्यादा कंपनियों का मिलना, चाहे नई कंपनी में या मौजूदा में से एक में।" } },
 { cat: "corporate", term: { en: "Demerger (spin-off)", hi: "डीमर्जर (स्पिन-ऑफ़)" }, def: { en: "Separating a division into its own company, with existing shareholders usually receiving shares in it.", hi: "किसी डिवीज़न को अलग कंपनी बनाना, जिसमें मौजूदा शेयरधारकों को आमतौर पर उसके शेयर मिलते हैं।" } },
 { cat: "corporate", term: { en: "Divestment", hi: "विनिवेश (Divestment)" }, def: { en: "Selling a stake or business unit. In India the term is also used for the government selling its stake in public-sector companies.", hi: "हिस्सेदारी या कारोबारी इकाई बेचना। भारत में सरकार के सार्वजनिक कंपनियों में हिस्सेदारी बेचने के लिए भी यह शब्द है।" } },
 { cat: "corporate", term: { en: "Leveraged buyout (LBO)", hi: "लीवरेज्ड बायआउट (LBO)" }, def: { en: "Buying a company with mostly borrowed money, with the target's own cash flows used to repay the debt.", hi: "ज़्यादातर उधार के पैसे से कंपनी ख़रीदना, जिसमें कर्ज़ लक्षित कंपनी के कैश फ़्लो से चुकाया जाता है।" } },
 { cat: "corporate", term: { en: "Due diligence", hi: "ड्यू डिलिजेंस" }, def: { en: "A detailed check of a company's finances, legal position and risks before an investment or acquisition.", hi: "निवेश या अधिग्रहण से पहले कंपनी के वित्त, क़ानूनी स्थिति और जोखिमों की विस्तृत जाँच।" } },
 { cat: "corporate", term: { en: "Conglomerate", hi: "कॉन्ग्लोमरेट (समूह)" }, def: { en: "A large group that owns businesses in several unrelated industries.", hi: "बड़ा समूह जिसके पास कई असंबंधित उद्योगों के कारोबार होते हैं।" } },
 { cat: "corporate", term: { en: "Holding company", hi: "होल्डिंग कंपनी" }, def: { en: "A company that exists mainly to own controlling stakes in other companies.", hi: "ऐसी कंपनी जो मुख्यतः दूसरी कंपनियों में नियंत्रक हिस्सेदारी रखने के लिए होती है।" } },
 { cat: "corporate", term: { en: "Subsidiary", hi: "सहायक कंपनी" }, def: { en: "A company controlled by another (its parent), usually through more than half of its voting shares.", hi: "दूसरी कंपनी (पैरेंट) के नियंत्रण वाली कंपनी, आमतौर पर आधे से ज़्यादा मतदान शेयरों के ज़रिए।" } },
 { cat: "corporate", term: { en: "Joint venture", hi: "जॉइंट वेंचर" }, def: { en: "A business set up and owned by two or more parties, who share its control, costs and profits.", hi: "दो या ज़्यादा पक्षों का बनाया और स्वामित्व वाला कारोबार, जिसमें वे नियंत्रण, लागत और मुनाफ़ा बाँटते हैं।" } },
 { cat: "corporate", term: { en: "LLP", hi: "LLP" }, def: { en: "Limited Liability Partnership: a partnership in which each partner's liability is limited to their agreed contribution.", hi: "लिमिटेड लायबिलिटी पार्टनरशिप: ऐसी साझेदारी जिसमें हर साझेदार की देनदारी उसके तय योगदान तक सीमित होती है।" } },
 { cat: "corporate", term: { en: "MSME", hi: "MSME" }, def: { en: "Micro, Small and Medium Enterprises: smaller businesses in India, classified by investment and turnover, which qualify for support schemes.", hi: "सूक्ष्म, लघु और मध्यम उद्यम: भारत के छोटे कारोबार, जो निवेश और टर्नओवर से वर्गीकृत होते हैं और सहायता योजनाओं के पात्र हैं।" } },
 { cat: "corporate", term: { en: "Bankruptcy and insolvency", hi: "दिवालियापन और इन्सॉल्वेंसी" }, def: { en: "Insolvency is being unable to pay debts when due; bankruptcy is the legal process that follows. India's main law is the IBC, 2016.", hi: "इन्सॉल्वेंसी यानी देय होने पर कर्ज़ न चुका पाना; बैंकरप्सी उसके बाद की क़ानूनी प्रक्रिया है। भारत का मुख्य क़ानून IBC, 2016 है।" } },
 { cat: "corporate", term: { en: "Angel investor", hi: "एंजेल निवेशक" }, def: { en: "A wealthy individual who invests personal money in an early-stage startup, usually in exchange for shares.", hi: "धनी व्यक्ति जो आमतौर पर शेयरों के बदले शुरुआती स्टार्टअप में अपना पैसा लगाता है।" } },
 { cat: "corporate", term: { en: "Venture capital", hi: "वेंचर कैपिटल" }, def: { en: "Professional investment in young, fast-growing companies in return for equity, at high risk.", hi: "तेज़ी से बढ़ती नई कंपनियों में इक्विटी के बदले पेशेवर निवेश, ऊँचे जोखिम के साथ।" } },
 { cat: "corporate", term: { en: "Private equity", hi: "प्राइवेट इक्विटी" }, def: { en: "Investment in companies not listed on an exchange, usually buying a large stake and aiming to sell at a profit in later years.", hi: "सूचीबद्ध न होने वाली कंपनियों में निवेश, आमतौर पर बड़ी हिस्सेदारी लेकर, बाद के वर्षों में लाभ पर बेचने के उद्देश्य से।" } },
 { cat: "corporate", term: { en: "Crowdfunding", hi: "क्राउडफ़ंडिंग" }, def: { en: "Raising small amounts from many people, usually online, for a project or cause.", hi: "किसी परियोजना या उद्देश्य के लिए बहुत से लोगों से थोड़ा-थोड़ा पैसा जुटाना, आमतौर पर ऑनलाइन।" } },

 // Economy and policy
 { cat: "economy", see: ["Reverse repo rate", "CRR (cash reserve ratio)", "SLR (statutory liquidity ratio)", "Monetary policy"], term: { en: "Repo rate", hi: "रेपो रेट" }, def: { en: "The rate at which the RBI lends short-term money to banks against securities. It is the main tool for influencing interest rates.", hi: "वह दर जिस पर RBI प्रतिभूतियों के बदले बैंकों को अल्पकालिक उधार देता है। ब्याज दरों को प्रभावित करने का यह मुख्य साधन है।" } },
 { cat: "economy", term: { en: "Reverse repo rate", hi: "रिवर्स रेपो रेट" }, def: { en: "The rate the RBI pays banks when it borrows from them against securities, which absorbs excess money from the system.", hi: "वह दर जो RBI बैंकों से प्रतिभूतियों के बदले उधार लेने पर देता है, जिससे प्रणाली का अतिरिक्त पैसा सोखा जाता है।" } },
 { cat: "economy", term: { en: "CRR (cash reserve ratio)", hi: "CRR (नकद आरक्षित अनुपात)" }, def: { en: "The share of a bank's deposits that it must keep with the RBI as cash. Raising it reduces the money banks can lend.", hi: "बैंक की जमा का वह हिस्सा जो उसे RBI के पास नकद रखना होता है। इसे बढ़ाने से बैंकों की उधार क्षमता घटती है।" } },
 { cat: "economy", term: { en: "SLR (statutory liquidity ratio)", hi: "SLR (वैधानिक तरलता अनुपात)" }, def: { en: "The share of a bank's deposits that it must hold in liquid assets such as cash, gold or government securities.", hi: "बैंक की जमा का वह हिस्सा जो उसे नकद, सोना या सरकारी प्रतिभूतियों जैसी तरल संपत्तियों में रखना होता है।" } },
 { cat: "economy", see: ["Repo rate", "Fiscal policy", "Inflation"], term: { en: "Monetary policy", hi: "मौद्रिक नीति" }, def: { en: "The RBI's management of interest rates and the money supply to keep inflation under control and support growth.", hi: "महँगाई नियंत्रित रखने और वृद्धि को सहारा देने के लिए RBI का ब्याज दरों और मुद्रा आपूर्ति का प्रबंधन।" } },
 { cat: "economy", see: ["Monetary policy", "Fiscal deficit", "Budget"], term: { en: "Fiscal policy", hi: "राजकोषीय नीति" }, def: { en: "The government's use of spending and taxation to influence the economy.", hi: "अर्थव्यवस्था को प्रभावित करने के लिए सरकार का ख़र्च और कराधान का उपयोग।" } },
 { cat: "economy", term: { en: "Budget", hi: "बजट" }, def: { en: "A plan of income and spending for a period. India's Union Budget sets out the government's receipts and expenditure for the year.", hi: "किसी अवधि की आय और ख़र्च की योजना। भारत का केंद्रीय बजट सरकार की साल की प्राप्तियाँ और ख़र्च बताता है।" } },
 { cat: "economy", term: { en: "Fiscal deficit", hi: "राजकोषीय घाटा" }, def: { en: "How much a government's total spending exceeds its income excluding borrowing. It shows how much it must borrow.", hi: "सरकार का कुल ख़र्च उधार छोड़कर उसकी आय से कितना ज़्यादा है। इससे पता चलता है कि उसे कितना उधार लेना होगा।" } },
 { cat: "economy", term: { en: "Budget surplus", hi: "बजट अधिशेष" }, def: { en: "When a government's income in a period is more than its spending.", hi: "जब किसी अवधि में सरकार की आय उसके ख़र्च से ज़्यादा हो।" } },
 { cat: "economy", see: ["Inflation", "Real and nominal GDP", "Recession"], term: { en: "GDP", hi: "GDP (सकल घरेलू उत्पाद)" }, def: { en: "Gross Domestic Product: the value of all final goods and services produced within a country in a period.", hi: "सकल घरेलू उत्पाद: किसी अवधि में देश के भीतर बनी सभी अंतिम वस्तुओं और सेवाओं का मूल्य।" } },
 { cat: "economy", term: { en: "Real and nominal GDP", hi: "वास्तविक और नाममात्र GDP" }, def: { en: "Nominal GDP is at current prices; real GDP removes the effect of price changes, and so shows true growth in output.", hi: "नाममात्र GDP मौजूदा कीमतों पर होता है; वास्तविक GDP कीमतों का असर हटाकर उत्पादन की असली वृद्धि दिखाता है।" } },
 { cat: "economy", term: { en: "CPI (consumer price index)", hi: "CPI (उपभोक्ता मूल्य सूचकांक)" }, def: { en: "An index of the prices households pay for a basket of goods and services. It is India's main measure of retail inflation.", hi: "घरों द्वारा वस्तुओं और सेवाओं की टोकरी के लिए दी जाने वाली कीमतों का सूचकांक। यह भारत में खुदरा महँगाई का मुख्य मापक है।" } },
 { cat: "economy", term: { en: "WPI (wholesale price index)", hi: "WPI (थोक मूल्य सूचकांक)" }, def: { en: "An index of prices at the wholesale level, which tracks price changes before goods reach consumers.", hi: "थोक स्तर की कीमतों का सूचकांक, जो वस्तुओं के उपभोक्ता तक पहुँचने से पहले के मूल्य बदलाव दिखाता है।" } },
 { cat: "economy", term: { en: "Deflation", hi: "अपस्फीति (Deflation)" }, def: { en: "A general fall in prices across the economy. It can make people delay spending and increases the real burden of debt.", hi: "अर्थव्यवस्था में कीमतों की सामान्य गिरावट। इससे लोग ख़र्च टाल सकते हैं और कर्ज़ का वास्तविक बोझ बढ़ता है।" } },
 { cat: "economy", term: { en: "Disinflation", hi: "डिसइन्फ़्लेशन" }, def: { en: "A slowing in the rate of inflation. Prices are still rising, but more slowly than before.", hi: "महँगाई की दर का धीमा होना। कीमतें अब भी बढ़ती हैं, पर पहले से धीमी गति से।" } },
 { cat: "economy", term: { en: "Stagflation", hi: "स्टैगफ़्लेशन" }, def: { en: "High inflation together with weak growth and high unemployment, which is hard for policymakers to treat.", hi: "ऊँची महँगाई के साथ कमज़ोर वृद्धि और ऊँची बेरोज़गारी, जिसका इलाज नीति निर्माताओं के लिए कठिन होता है।" } },
 { cat: "economy", term: { en: "Shrinkflation", hi: "श्रिंकफ़्लेशन" }, def: { en: "A product getting smaller at the same price, which is a hidden form of price rise.", hi: "उसी कीमत पर उत्पाद का छोटा होना, जो कीमत बढ़ने का छिपा रूप है।" } },
 { cat: "economy", term: { en: "Recession", hi: "मंदी (Recession)" }, def: { en: "A significant fall in economic activity. A common rule of thumb is two quarters in a row of falling real GDP.", hi: "आर्थिक गतिविधि में बड़ी गिरावट। एक प्रचलित पैमाना है लगातार दो तिमाहियों में वास्तविक GDP का गिरना।" } },
 { cat: "economy", term: { en: "Demonetisation", hi: "विमुद्रीकरण (Demonetisation)" }, def: { en: "Withdrawing the legal-tender status of a currency note, as India did with its old ₹500 and ₹1,000 notes in November 2016.", hi: "मुद्रा नोट की वैध मुद्रा की स्थिति वापस लेना, जैसे भारत ने नवंबर 2016 में पुराने ₹500 और ₹1,000 के नोटों के साथ किया।" } },
 { cat: "economy", term: { en: "Exchange rate", hi: "विनिमय दर" }, def: { en: "The price of one currency in terms of another, such as rupees per US dollar.", hi: "एक मुद्रा की दूसरी मुद्रा में कीमत, जैसे प्रति अमेरिकी डॉलर रुपये।" } },
 { cat: "economy", term: { en: "Forex", hi: "फ़ॉरेक्स" }, def: { en: "Foreign exchange: buying and selling currencies. In India, retail forex trading is allowed only in permitted pairs on recognised exchanges.", hi: "विदेशी मुद्रा: मुद्राओं की ख़रीद-बिक्री। भारत में खुदरा फ़ॉरेक्स ट्रेडिंग केवल मान्यता प्राप्त एक्सचेंजों पर अनुमत जोड़ों में वैध है।" } },
 { cat: "economy", term: { en: "Balance of payments", hi: "भुगतान संतुलन" }, def: { en: "A record of all money flowing between a country and the rest of the world, made up of the current and capital accounts.", hi: "देश और बाकी दुनिया के बीच सभी धन प्रवाह का रिकॉर्ड, जो चालू और पूँजी खातों से बनता है।" } },
 { cat: "economy", term: { en: "Current account deficit", hi: "चालू खाता घाटा" }, def: { en: "When a country pays more abroad for goods, services and transfers than it receives.", hi: "जब देश वस्तुओं, सेवाओं और हस्तांतरण के लिए विदेश से जितना पाता है, उससे ज़्यादा चुकाता है।" } },
 { cat: "economy", term: { en: "Direct tax", hi: "प्रत्यक्ष कर" }, def: { en: "Tax paid directly to the government by the person it is levied on, such as income tax and corporate tax.", hi: "जिस पर लगाया गया है वही व्यक्ति सीधे सरकार को देता है, जैसे आयकर और कॉर्पोरेट टैक्स।" } },
 { cat: "economy", term: { en: "Indirect tax", hi: "अप्रत्यक्ष कर" }, def: { en: "Tax collected by a seller from the buyer and passed on to the government, such as GST and customs duty.", hi: "विक्रेता द्वारा ख़रीदार से वसूलकर सरकार को दिया गया कर, जैसे GST और सीमा शुल्क।" } },
 { cat: "economy", term: { en: "GST", hi: "GST (वस्तु एवं सेवा कर)" }, def: { en: "Goods and Services Tax: India's main indirect tax on the supply of goods and services, which replaced many earlier taxes in 2017.", hi: "वस्तु एवं सेवा कर: वस्तुओं और सेवाओं की आपूर्ति पर भारत का मुख्य अप्रत्यक्ष कर, जिसने 2017 में कई पुराने करों की जगह ली।" } },
 { cat: "economy", term: { en: "Corporate tax", hi: "कॉर्पोरेट टैक्स" }, def: { en: "Tax that companies pay on their profits.", hi: "कंपनियों द्वारा अपने मुनाफ़े पर दिया जाने वाला कर।" } },
 { cat: "economy", term: { en: "ITR (income tax return)", hi: "ITR (आयकर रिटर्न)" }, def: { en: "The form in which you report your income and tax to the Income Tax Department for a financial year.", hi: "वह फ़ॉर्म जिसमें आप किसी वित्त वर्ष की अपनी आय और टैक्स आयकर विभाग को बताते हैं।" } },
 { cat: "economy", term: { en: "Surcharge", hi: "अधिभार (Surcharge)" }, def: { en: "An extra charge added on top of income tax for people or companies with income above set levels.", hi: "तय स्तर से ज़्यादा आय वाले लोगों या कंपनियों के आयकर पर लगने वाला अतिरिक्त शुल्क।" } },
 { cat: "economy", term: { en: "Subsidy", hi: "सब्सिडी" }, def: { en: "Government support that lowers the cost of something, such as fertiliser or fuel, for producers or consumers.", hi: "सरकारी सहायता जो उत्पादकों या उपभोक्ताओं के लिए उर्वरक या ईंधन जैसी चीज़ की लागत घटाती है।" } },
 { cat: "economy", term: { en: "Law of demand", hi: "माँग का नियम" }, def: { en: "Other things being equal, buyers want less of a product as its price rises, and more as it falls.", hi: "अन्य बातें समान रहने पर, कीमत बढ़ने पर ख़रीदार कम चाहते हैं और घटने पर ज़्यादा।" } },
 { cat: "economy", term: { en: "Law of supply", hi: "आपूर्ति का नियम" }, def: { en: "Other things being equal, producers offer more of a product as its price rises, and less as it falls.", hi: "अन्य बातें समान रहने पर, कीमत बढ़ने पर उत्पादक ज़्यादा देते हैं और घटने पर कम।" } },
 { cat: "economy", term: { en: "Monopoly", hi: "एकाधिकार (Monopoly)" }, def: { en: "A market with a single seller, which therefore has great power over the price.", hi: "एक ही विक्रेता वाला बाज़ार, जिसका कीमत पर बहुत नियंत्रण होता है।" } },
 { cat: "economy", term: { en: "Oligopoly", hi: "अल्पाधिकार (Oligopoly)" }, def: { en: "A market dominated by a few large sellers, such as India's telecom sector.", hi: "कुछ बड़े विक्रेताओं के प्रभुत्व वाला बाज़ार, जैसे भारत का दूरसंचार क्षेत्र।" } },
 { cat: "economy", term: { en: "Black swan event", hi: "ब्लैक स्वान घटना" }, def: { en: "A rare, unexpected event with a huge impact, which seems obvious only with hindsight.", hi: "दुर्लभ, अप्रत्याशित और बड़े असर वाली घटना, जो बाद में ही स्पष्ट लगती है।" } },
 { cat: "economy", term: { en: "Asset bubble", hi: "एसेट बबल" }, def: { en: "Prices of an asset rising far above reasonable value on speculation, usually followed by a sharp fall.", hi: "सट्टे से किसी एसेट की कीमत का उचित मूल्य से बहुत ऊपर जाना, जिसके बाद आमतौर पर तेज़ गिरावट आती है।" } },
 { cat: "economy", term: { en: "IMF", hi: "IMF (अंतरराष्ट्रीय मुद्रा कोष)" }, def: { en: "International Monetary Fund: a global institution that monitors economies and lends to countries in balance-of-payments difficulty.", hi: "अंतरराष्ट्रीय मुद्रा कोष: वैश्विक संस्था जो अर्थव्यवस्थाओं पर नज़र रखती है और भुगतान संकट वाले देशों को उधार देती है।" } },
 { cat: "economy", term: { en: "WTO", hi: "WTO (विश्व व्यापार संगठन)" }, def: { en: "World Trade Organization: the global body that sets rules for trade between countries and settles trade disputes.", hi: "विश्व व्यापार संगठन: देशों के बीच व्यापार के नियम बनाने और व्यापार विवाद सुलझाने वाली वैश्विक संस्था।" } },
 { cat: "economy", term: { en: "Money laundering", hi: "मनी लॉन्ड्रिंग" }, def: { en: "Passing money from crime through transactions to make it look legal. In India it is an offence under the PMLA.", hi: "अपराध से मिले पैसे को लेनदेन से गुज़ारकर वैध दिखाना। भारत में यह PMLA के तहत अपराध है।" } },

 // Markets, investing and mutual funds
 { cat: "basics", see: ["NSE and BSE", "SEBI", "Share (stock)", "Index"], term: { en: "Stock market", hi: "शेयर बाज़ार" }, def: { en: "The regulated marketplace where shares of listed companies are issued and traded through stock exchanges.", hi: "वह विनियमित बाज़ार जहाँ सूचीबद्ध कंपनियों के शेयर स्टॉक एक्सचेंज के ज़रिए जारी और ट्रेड होते हैं।" } },
 { cat: "basics", term: { en: "Primary market", hi: "प्राथमिक बाज़ार" }, def: { en: "Where securities are sold for the first time and the money goes to the issuing company, as in an IPO.", hi: "जहाँ प्रतिभूतियाँ पहली बार बिकती हैं और पैसा जारी करने वाली कंपनी को मिलता है, जैसे IPO में।" } },
 { cat: "basics", term: { en: "Secondary market", hi: "द्वितीयक बाज़ार" }, def: { en: "Where investors trade existing securities with each other on an exchange. The company gets no money from these trades.", hi: "जहाँ निवेशक मौजूदा प्रतिभूतियों का एक्सचेंज पर आपस में लेनदेन करते हैं। इन सौदों से कंपनी को पैसा नहीं मिलता।" } },
 { cat: "basics", term: { en: "Securities", hi: "प्रतिभूतियाँ (Securities)" }, def: { en: "Tradable financial instruments such as shares, bonds, debentures, mutual fund units and derivatives.", hi: "ट्रेड योग्य वित्तीय साधन, जैसे शेयर, बॉन्ड, डिबेंचर, म्यूचुअल फ़ंड यूनिट और डेरिवेटिव।" } },
 { cat: "basics", term: { en: "Blue-chip stocks", hi: "ब्लू-चिप शेयर" }, def: { en: "Shares of large, established companies known for stable business and long records of performance.", hi: "बड़ी, स्थापित कंपनियों के शेयर, जो स्थिर कारोबार और लंबे प्रदर्शन के लिए जानी जाती हैं।" } },
 { cat: "basics", term: { en: "Large, mid and small cap", hi: "लार्ज, मिड और स्मॉल कैप" }, def: { en: "SEBI's size groups: the top 100 companies by market cap are large cap, the next 150 are mid cap, and the rest are small cap.", hi: "SEBI के आकार समूह: मार्केट कैप में शीर्ष 100 कंपनियाँ लार्ज कैप, अगली 150 मिड कैप और बाकी स्मॉल कैप।" } },
 { cat: "basics", term: { en: "Penny stocks", hi: "पेनी स्टॉक" }, def: { en: "Very low-priced shares of small companies. They are illiquid, risky and often the target of price manipulation.", hi: "छोटी कंपनियों के बहुत कम कीमत वाले शेयर। ये कम लिक्विड, जोखिम भरे और अक्सर कीमत में हेराफेरी का निशाना होते हैं।" } },
 { cat: "basics", term: { en: "Retail investor", hi: "रिटेल निवेशक" }, def: { en: "An individual investing their own money, as opposed to an institution such as a mutual fund or insurer.", hi: "अपना पैसा लगाने वाला व्यक्ति, म्यूचुअल फ़ंड या बीमा कंपनी जैसी संस्था के विपरीत।" } },
 { cat: "basics", term: { en: "Institutional investor", hi: "संस्थागत निवेशक" }, def: { en: "An organisation that invests large pools of money, such as a mutual fund, pension fund, bank or insurer.", hi: "बड़ी राशि निवेश करने वाला संगठन, जैसे म्यूचुअल फ़ंड, पेंशन फ़ंड, बैंक या बीमा कंपनी।" } },
 { cat: "basics", term: { en: "HNI", hi: "HNI (उच्च नेट वर्थ व्यक्ति)" }, def: { en: "High Net Worth Individual: a person with substantial investable wealth. In IPOs, this is the category of those applying above the retail limit.", hi: "उच्च नेट वर्थ व्यक्ति: बड़ी निवेश योग्य संपत्ति वाला व्यक्ति। IPO में खुदरा सीमा से ऊपर आवेदन करने वालों की श्रेणी।" } },
 { cat: "basics", term: { en: "Capital gain", hi: "पूँजीगत लाभ" }, def: { en: "The profit made on selling an asset such as shares or property for more than its purchase cost. It is taxed by holding period.", hi: "शेयर या संपत्ति जैसे एसेट को लागत से ज़्यादा में बेचने पर हुआ लाभ। इस पर होल्डिंग अवधि के अनुसार टैक्स लगता है।" } },
 { cat: "basics", term: { en: "Rate of return", hi: "रिटर्न की दर" }, def: { en: "The gain or loss on an investment over a period, as a percentage of the amount invested.", hi: "किसी अवधि में निवेश पर लाभ या हानि, लगाई गई राशि के प्रतिशत में।" } },
 { cat: "basics", term: { en: "Lump sum", hi: "एकमुश्त (Lump sum)" }, def: { en: "Investing or paying a whole amount at one time rather than in instalments.", hi: "किस्तों के बजाय पूरी राशि एक साथ निवेश करना या चुकाना।" } },
 { cat: "basics", term: { en: "Risk appetite", hi: "जोखिम क्षमता (Risk appetite)" }, def: { en: "How much loss and fluctuation you are willing and able to accept in pursuit of returns.", hi: "रिटर्न के लिए आप कितना नुकसान और उतार-चढ़ाव स्वीकार करने को तैयार और सक्षम हैं।" } },
 { cat: "basics", term: { en: "Investment horizon", hi: "निवेश अवधि" }, def: { en: "How long you plan to stay invested before you need the money. It guides how much risk is sensible.", hi: "पैसे की ज़रूरत पड़ने से पहले आप कितने समय निवेशित रहना चाहते हैं। इससे तय होता है कि कितना जोखिम उचित है।" } },
 { cat: "basics", term: { en: "Rebalancing", hi: "रीबैलेंसिंग" }, def: { en: "Buying and selling periodically to bring a portfolio back to its target asset allocation.", hi: "पोर्टफ़ोलियो को लक्षित एसेट एलोकेशन पर वापस लाने के लिए समय-समय पर ख़रीद-बिक्री करना।" } },
 { cat: "basics", term: { en: "Portfolio", hi: "पोर्टफ़ोलियो" }, def: { en: "All the investments a person or institution holds, such as shares, funds, bonds and gold.", hi: "किसी व्यक्ति या संस्था के सभी निवेश, जैसे शेयर, फ़ंड, बॉन्ड और सोना।" } },
 { cat: "basics", see: ["CAPM", "Alpha", "Sharpe ratio"], term: { en: "Beta", hi: "बीटा" }, def: { en: "How much a share tends to move compared with the market. A beta of 1.2 suggests about 12% move for a 10% market move.", hi: "बाज़ार की तुलना में शेयर कितना चलता है। 1.2 बीटा का मतलब बाज़ार के 10% बदलाव पर लगभग 12% बदलाव।" } },
 { cat: "basics", term: { en: "Alpha", hi: "अल्फ़ा" }, def: { en: "The return of an investment above what its risk and benchmark would predict. It is a common measure of a fund manager's skill.", hi: "जोखिम और बेंचमार्क के अनुमान से ऊपर निवेश का रिटर्न। यह फ़ंड मैनेजर के कौशल का आम मापक है।" } },
 { cat: "basics", term: { en: "CAPM", hi: "CAPM" }, def: { en: "Capital Asset Pricing Model: expected return = risk-free rate + beta × (market return − risk-free rate).", hi: "कैपिटल एसेट प्राइसिंग मॉडल: अपेक्षित रिटर्न = जोखिम-मुक्त दर + बीटा × (बाज़ार रिटर्न − जोखिम-मुक्त दर)।" } },
 { cat: "basics", term: { en: "Sharpe ratio", hi: "शार्प अनुपात" }, def: { en: "Return above the risk-free rate, divided by standard deviation. It shows the return earned per unit of total risk.", hi: "जोखिम-मुक्त दर से ऊपर का रिटर्न ÷ मानक विचलन। यह कुल जोखिम की प्रति इकाई पर मिला रिटर्न दिखाता है।" } },
 { cat: "basics", term: { en: "Sortino ratio", hi: "सॉर्टिनो अनुपात" }, def: { en: "Like the Sharpe ratio, but it counts only downside volatility as risk.", hi: "शार्प अनुपात जैसा, पर इसमें केवल नीचे की ओर की अस्थिरता को जोखिम माना जाता है।" } },
 { cat: "basics", term: { en: "Standard deviation", hi: "मानक विचलन" }, def: { en: "A statistical measure of how widely returns vary around their average. It is the most common measure of investment risk.", hi: "सांख्यिकीय मापक कि रिटर्न अपने औसत के आसपास कितना फैलते हैं। यह निवेश जोखिम का सबसे आम मापक है।" } },
 { cat: "basics", term: { en: "Efficient frontier", hi: "एफ़िशिएंट फ़्रंटियर" }, def: { en: "In portfolio theory, the set of portfolios offering the highest expected return for each level of risk.", hi: "पोर्टफ़ोलियो सिद्धांत में, हर जोखिम स्तर पर सबसे ज़्यादा अपेक्षित रिटर्न देने वाले पोर्टफ़ोलियो का समूह।" } },
 { cat: "basics", term: { en: "Value investing", hi: "वैल्यू निवेश" }, def: { en: "Buying shares that seem priced below their intrinsic value and waiting for the market to recognise it.", hi: "आंतरिक मूल्य से कम कीमत वाले दिखने वाले शेयर ख़रीदना और बाज़ार के पहचानने का इंतज़ार करना।" } },
 { cat: "basics", term: { en: "Growth investing", hi: "ग्रोथ निवेश" }, def: { en: "Buying companies expected to grow faster than average, even if their shares look expensive on today's earnings.", hi: "औसत से तेज़ बढ़ने की उम्मीद वाली कंपनियाँ ख़रीदना, भले ही आज की कमाई पर शेयर महँगे दिखें।" } },
 { cat: "basics", term: { en: "Momentum investing", hi: "मोमेंटम निवेश" }, def: { en: "Buying what has been rising and avoiding what has been falling, on the view that recent trends continue for a while.", hi: "बढ़ते शेयर ख़रीदना और गिरते से बचना, इस सोच के साथ कि हाल के रुझान कुछ समय जारी रहते हैं।" } },
 { cat: "basics", term: { en: "ESG investing", hi: "ESG निवेश" }, def: { en: "Weighing environmental, social and governance factors alongside financial ones when choosing investments.", hi: "निवेश चुनते समय वित्तीय बातों के साथ पर्यावरण, सामाजिक और गवर्नेंस पहलुओं को भी देखना।" } },
 { cat: "basics", term: { en: "Anchoring", hi: "एंकरिंग" }, def: { en: "A behavioural bias of relying too much on a first number seen, such as the price you paid for a share.", hi: "व्यवहारगत पूर्वाग्रह, जिसमें पहले दिखे आँकड़े, जैसे शेयर की ख़रीद कीमत, पर ज़रूरत से ज़्यादा भरोसा किया जाता है।" } },
 { cat: "basics", term: { en: "Recency bias", hi: "रीसेंसी बायस" }, def: { en: "Giving too much weight to recent events, such as expecting last year's returns to repeat.", hi: "हाल की घटनाओं को ज़्यादा महत्व देना, जैसे यह उम्मीद करना कि पिछले साल का रिटर्न दोहराएगा।" } },
 { cat: "basics", term: { en: "Commodity", hi: "कमोडिटी" }, def: { en: "A basic traded good such as gold, crude oil or wheat, largely the same whoever produces it.", hi: "सोना, कच्चा तेल या गेहूँ जैसी बुनियादी ट्रेड होने वाली वस्तु, जो लगभग समान होती है चाहे कोई भी बनाए।" } },
 { cat: "basics", term: { en: "Real estate", hi: "रियल एस्टेट" }, def: { en: "Land and buildings as an investment. It can provide rent and price growth but is illiquid and costly to trade.", hi: "निवेश के रूप में ज़मीन और भवन। इससे किराया और कीमत बढ़त मिल सकती है, पर यह कम लिक्विड और ट्रेड में महँगा है।" } },
 { cat: "basics", term: { en: "Cryptocurrency", hi: "क्रिप्टोकरेंसी" }, def: { en: "A digital asset such as Bitcoin that runs on a blockchain. It is not legal tender in India, is highly volatile, and gains are heavily taxed.", hi: "ब्लॉकचेन पर चलने वाला डिजिटल एसेट, जैसे Bitcoin। यह भारत में वैध मुद्रा नहीं है, बहुत अस्थिर है और लाभ पर भारी टैक्स है।" } },
 { cat: "trading", term: { en: "LTP (last traded price)", hi: "LTP (अंतिम ट्रेड कीमत)" }, def: { en: "The price at which a stock's most recent trade took place. It is the price usually shown on screen.", hi: "वह कीमत जिस पर शेयर का सबसे हालिया सौदा हुआ। स्क्रीन पर आमतौर पर यही दिखती है।" } },
 { cat: "trading", term: { en: "Bracket order", hi: "ब्रैकेट ऑर्डर" }, def: { en: "An entry order placed together with a target and a stop-loss, so that one exit cancels the other.", hi: "लक्ष्य और स्टॉप-लॉस के साथ दिया गया एंट्री ऑर्डर, जिसमें एक निकासी दूसरे को रद्द कर देती है।" } },
 { cat: "trading", term: { en: "BTST", hi: "BTST (आज ख़रीदें, कल बेचें)" }, def: { en: "Buy Today, Sell Tomorrow: selling shares before they reach your demat account, which carries a risk if the seller fails to deliver.", hi: "आज ख़रीदें, कल बेचें: डीमैट खाते में आने से पहले शेयर बेचना; विक्रेता के डिलीवरी न देने पर इसमें जोखिम है।" } },
 { cat: "trading", term: { en: "Algo trading", hi: "एल्गो ट्रेडिंग" }, def: { en: "Using computer programs to place orders automatically according to set rules. Retail algos in India must follow SEBI and exchange rules.", hi: "तय नियमों के अनुसार कंप्यूटर प्रोग्राम से अपने आप ऑर्डर देना। भारत में रिटेल एल्गो को SEBI और एक्सचेंज के नियम मानने होते हैं।" } },
 { cat: "trading", term: { en: "Bull trap", hi: "बुल ट्रैप" }, def: { en: "A false rise above resistance that draws in buyers just before the price turns back down.", hi: "रेज़िस्टेंस के ऊपर झूठी तेज़ी, जो कीमत नीचे पलटने से ठीक पहले ख़रीदारों को खींच लेती है।" } },
 { cat: "trading", term: { en: "Bear trap", hi: "बेयर ट्रैप" }, def: { en: "A false fall below support that draws in sellers just before the price turns back up.", hi: "सपोर्ट के नीचे झूठी गिरावट, जो कीमत ऊपर पलटने से ठीक पहले विक्रेताओं को खींच लेती है।" } },
 { cat: "trading", term: { en: "Bulk deal", hi: "बल्क डील" }, def: { en: "A trade or trades by one client in more than 0.5% of a company's listed shares in a day. Exchanges publish them.", hi: "एक दिन में किसी ग्राहक का कंपनी के सूचीबद्ध शेयरों के 0.5% से ज़्यादा का सौदा। एक्सचेंज इन्हें प्रकाशित करते हैं।" } },
 { cat: "trading", term: { en: "Block deal", hi: "ब्लॉक डील" }, def: { en: "A large trade between two parties in a separate window of the exchange, within a set price range.", hi: "दो पक्षों के बीच एक्सचेंज की अलग विंडो में, तय कीमत सीमा के भीतर बड़ा सौदा।" } },
 { cat: "trading", term: { en: "Insider trading", hi: "इनसाइडर ट्रेडिंग" }, def: { en: "Trading on important company information that is not yet public. It is illegal under SEBI rules.", hi: "कंपनी की ऐसी महत्वपूर्ण जानकारी पर ट्रेड करना जो अभी सार्वजनिक नहीं। SEBI नियमों के तहत यह अवैध है।" } },
 { cat: "trading", term: { en: "Market maker", hi: "मार्केट मेकर" }, def: { en: "A firm that continuously quotes buy and sell prices for a security, which adds liquidity and earns the spread.", hi: "फ़र्म जो किसी प्रतिभूति के ख़रीद और बिक्री भाव लगातार देती है, जिससे लिक्विडिटी बढ़ती है और वह स्प्रेड कमाती है।" } },
 { cat: "trading", term: { en: "Dark pool", hi: "डार्क पूल" }, def: { en: "A private venue abroad for large trades, where orders are not visible to the public before execution.", hi: "विदेशों में बड़े सौदों का निजी स्थान, जहाँ ऑर्डर पूरा होने से पहले जनता को नहीं दिखते।" } },
 { cat: "trading", term: { en: "Market breadth", hi: "मार्केट ब्रेड्थ" }, def: { en: "How many shares are taking part in a market move, for example the number of advances compared with declines.", hi: "बाज़ार की चाल में कितने शेयर शामिल हैं, जैसे बढ़ने वाले और गिरने वाले शेयरों की संख्या की तुलना।" } },
 { cat: "trading", term: { en: "Capitulation", hi: "कैपिट्यूलेशन" }, def: { en: "Heavy panic selling at the end of a sharp fall, when many holders give up. It can precede a bottom, but this is known only later.", hi: "तेज़ गिरावट के अंत में घबराहट की भारी बिकवाली, जब बहुत से धारक हार मान लेते हैं। यह तल से पहले हो सकती है, पर पता बाद में चलता है।" } },
 { cat: "trading", term: { en: "ASM and GSM", hi: "ASM और GSM" }, def: { en: "Additional and Graded Surveillance Measures: exchange lists that put tighter trading limits and margins on shares showing unusual price moves.", hi: "अतिरिक्त और ग्रेडेड निगरानी उपाय: एक्सचेंज की सूचियाँ जो असामान्य चाल वाले शेयरों पर कड़ी ट्रेडिंग सीमा और मार्जिन लगाती हैं।" } },
 { cat: "trading", term: { en: "Average true range (ATR)", hi: "एवरेज ट्रू रेंज (ATR)" }, def: { en: "An indicator of volatility that averages each day's full trading range, including gaps.", hi: "अस्थिरता का इंडिकेटर, जो गैप सहित हर दिन की पूरी ट्रेडिंग रेंज का औसत निकालता है।" } },
 { cat: "trading", term: { en: "Sentiment indicators", hi: "सेंटीमेंट इंडिकेटर" }, def: { en: "Measures of the market's mood, such as India VIX or the put-call ratio.", hi: "बाज़ार के मूड के मापक, जैसे India VIX या पुट-कॉल अनुपात।" } },
 { cat: "trading", term: { en: "India VIX", hi: "India VIX" }, def: { en: "NSE's volatility index, which shows how much movement the options market expects in NIFTY over the next 30 days.", hi: "NSE का वोलैटिलिटी इंडेक्स, जो दिखाता है कि ऑप्शन बाज़ार अगले 30 दिनों में NIFTY में कितनी चाल की उम्मीद करता है।" } },
 { cat: "india", term: { en: "NSDL and CDSL", hi: "NSDL और CDSL" }, def: { en: "India's two securities depositories, which hold shares and other securities in electronic form for investors.", hi: "भारत की दो प्रतिभूति डिपॉज़िटरी, जो निवेशकों के शेयर और अन्य प्रतिभूतियाँ इलेक्ट्रॉनिक रूप में रखती हैं।" } },
 { cat: "india", term: { en: "RBI", hi: "RBI (भारतीय रिज़र्व बैंक)" }, def: { en: "Reserve Bank of India: the central bank, which issues currency, sets monetary policy and regulates banks.", hi: "भारतीय रिज़र्व बैंक: केंद्रीय बैंक, जो मुद्रा जारी करता है, मौद्रिक नीति तय करता है और बैंकों को नियंत्रित करता है।" } },
 { cat: "india", term: { en: "IRDAI", hi: "IRDAI" }, def: { en: "Insurance Regulatory and Development Authority of India: the regulator of insurance companies and policies.", hi: "भारतीय बीमा विनियामक और विकास प्राधिकरण: बीमा कंपनियों और पॉलिसियों का नियामक।" } },
 { cat: "india", term: { en: "PFRDA", hi: "PFRDA" }, def: { en: "Pension Fund Regulatory and Development Authority: the regulator of the National Pension System and pension funds.", hi: "पेंशन फ़ंड विनियामक और विकास प्राधिकरण: नेशनल पेंशन सिस्टम और पेंशन फ़ंड का नियामक।" } },
 { cat: "india", term: { en: "AMFI", hi: "AMFI" }, def: { en: "Association of Mutual Funds in India: the industry body of mutual fund houses, which also registers distributors.", hi: "भारत में म्यूचुअल फ़ंड का संघ: फ़ंड हाउसों की उद्योग संस्था, जो वितरकों का पंजीकरण भी करती है।" } },
 { cat: "india", term: { en: "Book building", hi: "बुक बिल्डिंग" }, def: { en: "An IPO pricing method in which investors bid within a price band, and the final price is set from the demand received.", hi: "IPO की कीमत तय करने का तरीका, जिसमें निवेशक प्राइस बैंड में बोली लगाते हैं और अंतिम कीमत माँग से तय होती है।" } },
 { cat: "india", term: { en: "FPO", hi: "FPO" }, def: { en: "Follow-on Public Offer: a further public sale of shares by a company that is already listed.", hi: "फ़ॉलो-ऑन पब्लिक ऑफ़र: पहले से सूचीबद्ध कंपनी द्वारा जनता को शेयरों की आगे की बिक्री।" } },
 { cat: "india", term: { en: "Green shoe option", hi: "ग्रीन शू विकल्प" }, def: { en: "An option in a public issue to allot extra shares if demand is strong, which helps keep the price stable after listing.", hi: "सार्वजनिक निर्गम में माँग मज़बूत होने पर अतिरिक्त शेयर देने का विकल्प, जो लिस्टिंग के बाद कीमत स्थिर रखने में मदद करता है।" } },
 { cat: "india", term: { en: "QIP", hi: "QIP" }, def: { en: "Qualified Institutions Placement: a quick way for a listed company to raise money by selling shares to institutional investors.", hi: "क्वालिफ़ाइड इंस्टीट्यूशंस प्लेसमेंट: सूचीबद्ध कंपनी का संस्थागत निवेशकों को शेयर बेचकर जल्दी पैसा जुटाने का तरीका।" } },
 { cat: "india", term: { en: "DRHP", hi: "DRHP" }, def: { en: "Draft Red Herring Prospectus: the document a company files with SEBI before an IPO, describing its business, finances and risks.", hi: "ड्राफ़्ट रेड हेरिंग प्रॉस्पेक्टस: IPO से पहले SEBI में दाखिल दस्तावेज़, जिसमें कारोबार, वित्त और जोखिम बताए जाते हैं।" } },
 { cat: "india", term: { en: "GIFT City", hi: "GIFT City" }, def: { en: "Gujarat International Finance Tec-City: India's international financial services centre, with its own exchanges and rules.", hi: "गुजरात इंटरनेशनल फ़ाइनेंस टेक-सिटी: भारत का अंतरराष्ट्रीय वित्तीय सेवा केंद्र, जिसके अपने एक्सचेंज और नियम हैं।" } },
 { cat: "india", term: { en: "DDPI", hi: "DDPI" }, def: { en: "Demat Debit and Pledge Instruction: a limited authorisation that lets a broker debit shares from your demat account to settle sales you make.", hi: "डीमैट डेबिट एंड प्लेज इंस्ट्रक्शन: सीमित अधिकार, जिससे ब्रोकर आपकी बिक्री के निपटान के लिए डीमैट खाते से शेयर डेबिट कर सकता है।" } },
 { cat: "india", term: { en: "Tax-loss harvesting", hi: "टैक्स-लॉस हार्वेस्टिंग" }, def: { en: "Selling investments at a loss to set the loss against taxable gains, within the tax rules.", hi: "टैक्स नियमों के भीतर, नुकसान वाले निवेश बेचकर उस नुकसान को कर योग्य लाभ से समायोजित करना।" } },
 { cat: "funds", see: ["Mutual fund", "NAV (net asset value)"], term: { en: "AUM (assets under management)", hi: "AUM (प्रबंधित संपत्ति)" }, def: { en: "The total market value of the investments a fund or manager looks after.", hi: "फ़ंड या मैनेजर द्वारा संभाले गए निवेशों का कुल बाज़ार मूल्य।" } },
 { cat: "funds", see: ["Regular plan", "Expense ratio"], term: { en: "Direct plan", hi: "डायरेक्ट प्लान" }, def: { en: "A mutual fund plan bought straight from the fund house with no distributor commission, so its expense ratio is lower.", hi: "बिना वितरक कमीशन के सीधे फ़ंड हाउस से ख़रीदा गया प्लान, इसलिए एक्सपेंस रेशियो कम होता है।" } },
 { cat: "funds", term: { en: "Regular plan", hi: "रेगुलर प्लान" }, def: { en: "A mutual fund plan bought through a distributor. It costs more than a direct plan because it includes commission.", hi: "वितरक के ज़रिए ख़रीदा गया प्लान। इसमें कमीशन शामिल होने से यह डायरेक्ट प्लान से महँगा होता है।" } },
 { cat: "funds", see: ["Debt fund", "Hybrid fund", "Index fund"], term: { en: "Equity fund", hi: "इक्विटी फ़ंड" }, def: { en: "A mutual fund that invests mainly in shares. It suits long horizons and carries market risk.", hi: "मुख्यतः शेयरों में निवेश करने वाला फ़ंड। यह लंबी अवधि के लिए उपयुक्त है और इसमें बाज़ार जोखिम होता है।" } },
 { cat: "funds", term: { en: "Debt fund", hi: "डेट फ़ंड" }, def: { en: "A mutual fund that invests in bonds and money market instruments. It is generally steadier than equity but not risk-free.", hi: "बॉन्ड और मुद्रा बाज़ार साधनों में निवेश करने वाला फ़ंड। यह आमतौर पर इक्विटी से स्थिर है पर जोखिम-मुक्त नहीं।" } },
 { cat: "funds", term: { en: "Hybrid fund", hi: "हाइब्रिड फ़ंड" }, def: { en: "A mutual fund that invests in a mix of equity and debt, and sometimes gold, in set proportions.", hi: "इक्विटी और डेट, कभी-कभी सोने के भी, तय अनुपात के मिश्रण में निवेश करने वाला फ़ंड।" } },
 { cat: "funds", term: { en: "Liquid fund", hi: "लिक्विड फ़ंड" }, def: { en: "A debt fund that invests in instruments maturing within 91 days. It is used to park short-term money.", hi: "91 दिन में परिपक्व होने वाले साधनों में निवेश करने वाला डेट फ़ंड। यह थोड़े समय के लिए पैसा रखने के काम आता है।" } },
 { cat: "funds", term: { en: "Sector fund", hi: "सेक्टर फ़ंड" }, def: { en: "An equity fund that invests in one sector, such as banking or technology. It is less diversified and so riskier.", hi: "बैंकिंग या टेक्नोलॉजी जैसे एक क्षेत्र में निवेश करने वाला इक्विटी फ़ंड। कम विविधता के कारण ज़्यादा जोखिम भरा।" } },
 { cat: "funds", term: { en: "Contra fund", hi: "कॉन्ट्रा फ़ंड" }, def: { en: "An equity fund that takes a contrarian approach, buying what is currently out of favour.", hi: "इक्विटी फ़ंड जो उलटी सोच अपनाता है और वह ख़रीदता है जो अभी पसंद नहीं किया जा रहा।" } },
 { cat: "funds", term: { en: "ETF", hi: "ETF (एक्सचेंज ट्रेडेड फ़ंड)" }, def: { en: "Exchange-Traded Fund: a fund, usually tracking an index or gold, whose units trade on an exchange like shares.", hi: "एक्सचेंज ट्रेडेड फ़ंड: आमतौर पर इंडेक्स या सोने को ट्रैक करने वाला फ़ंड, जिसकी यूनिट शेयरों की तरह एक्सचेंज पर ट्रेड होती हैं।" } },
 { cat: "funds", term: { en: "REIT", hi: "REIT" }, def: { en: "Real Estate Investment Trust: a listed trust that owns income-producing property and distributes most of the income to unit holders.", hi: "रियल एस्टेट इन्वेस्टमेंट ट्रस्ट: आय देने वाली संपत्ति का सूचीबद्ध ट्रस्ट, जो ज़्यादातर आय यूनिट धारकों को बाँटता है।" } },
 { cat: "funds", term: { en: "InvIT", hi: "InvIT" }, def: { en: "Infrastructure Investment Trust: like a REIT, but it owns infrastructure assets such as roads or power lines.", hi: "इन्फ़्रास्ट्रक्चर इन्वेस्टमेंट ट्रस्ट: REIT जैसा, पर इसके पास सड़क या बिजली लाइन जैसी बुनियादी ढाँचा संपत्तियाँ होती हैं।" } },
 { cat: "funds", term: { en: "Hedge fund", hi: "हेज फ़ंड" }, def: { en: "A private fund for wealthy investors that uses flexible strategies such as short selling and leverage.", hi: "धनी निवेशकों का निजी फ़ंड, जो शॉर्ट सेलिंग और लीवरेज जैसी लचीली रणनीतियाँ अपनाता है।" } },
 { cat: "funds", term: { en: "AIF", hi: "AIF" }, def: { en: "Alternative Investment Fund: a SEBI-regulated pooled fund for sophisticated investors, covering areas such as private equity and hedge funds.", hi: "ऑल्टरनेटिव इन्वेस्टमेंट फ़ंड: अनुभवी निवेशकों के लिए SEBI-नियंत्रित सामूहिक फ़ंड, जिसमें प्राइवेट इक्विटी और हेज फ़ंड जैसे क्षेत्र आते हैं।" } },
 { cat: "funds", term: { en: "PMS", hi: "PMS" }, def: { en: "Portfolio Management Service: a SEBI-regulated service that manages a personal portfolio for larger investors, with a minimum of ₹50 lakh.", hi: "पोर्टफ़ोलियो मैनेजमेंट सर्विस: बड़े निवेशकों का निजी पोर्टफ़ोलियो संभालने वाली SEBI-नियंत्रित सेवा, न्यूनतम ₹50 लाख।" } },
 { cat: "funds", term: { en: "Benchmark", hi: "बेंचमार्क" }, def: { en: "A standard such as NIFTY 50 against which a fund's or portfolio's performance is compared.", hi: "NIFTY 50 जैसा मानक, जिससे फ़ंड या पोर्टफ़ोलियो के प्रदर्शन की तुलना की जाती है।" } },
 { cat: "funds", term: { en: "Exit load", hi: "एग्ज़िट लोड" }, def: { en: "A fee some mutual funds charge when you redeem units within a set period.", hi: "कुछ म्यूचुअल फ़ंड का शुल्क, जो तय अवधि के भीतर यूनिट भुनाने पर लगता है।" } },
 { cat: "funds", term: { en: "Redemption", hi: "रिडेम्प्शन" }, def: { en: "Selling mutual fund units back to the fund, or a bond being repaid at maturity.", hi: "म्यूचुअल फ़ंड यूनिट फ़ंड को वापस बेचना, या परिपक्वता पर बॉन्ड का चुकाया जाना।" } },
 { cat: "funds", term: { en: "STP and SWP", hi: "STP और SWP" }, def: { en: "A systematic transfer plan moves money regularly from one fund to another; a systematic withdrawal plan pays you a regular amount from a fund.", hi: "STP से पैसा नियमित रूप से एक फ़ंड से दूसरे में जाता है; SWP से फ़ंड से आपको नियमित राशि मिलती है।" } },
 { cat: "funds", term: { en: "XIRR", hi: "XIRR" }, def: { en: "A yearly return worked out for cash flows on irregular dates. It is the right way to measure SIP returns.", hi: "अनियमित तारीख़ों के कैश फ़्लो पर निकाला गया सालाना रिटर्न। SIP का रिटर्न मापने का यही सही तरीका है।" } },
 { cat: "funds", term: { en: "Goal-based investing", hi: "लक्ष्य-आधारित निवेश" }, def: { en: "Choosing investments for each specific goal based on its amount, date and how much risk it can take.", hi: "हर ख़ास लक्ष्य के लिए उसकी राशि, तारीख़ और जोखिम क्षमता के आधार पर निवेश चुनना।" } },
 { cat: "derivatives", see: ["Futures", "Option", "Forward contract", "Swap"], term: { en: "Derivative", hi: "डेरिवेटिव" }, def: { en: "A contract whose value comes from an underlying asset such as a share, index, commodity or currency.", hi: "ऐसा अनुबंध जिसका मूल्य किसी अंतर्निहित एसेट, जैसे शेयर, इंडेक्स, कमोडिटी या मुद्रा, से आता है।" } },
 { cat: "derivatives", term: { en: "Forward contract", hi: "फ़ॉरवर्ड अनुबंध" }, def: { en: "A private agreement to buy or sell an asset at a set price on a future date. It is customised and not traded on an exchange.", hi: "भविष्य की तारीख़ पर तय कीमत पर एसेट ख़रीदने या बेचने का निजी समझौता। यह अनुकूलित होता है और एक्सचेंज पर ट्रेड नहीं होता।" } },
 { cat: "derivatives", term: { en: "Swap", hi: "स्वैप" }, def: { en: "A contract to exchange cash flows, such as fixed-rate interest for floating-rate interest, for a set period.", hi: "तय अवधि के लिए कैश फ़्लो बदलने का अनुबंध, जैसे तय दर का ब्याज बदले फ़्लोटिंग दर का ब्याज।" } },
 { cat: "derivatives", term: { en: "Hedging", hi: "हेजिंग" }, def: { en: "Taking a position that offsets the risk of another, such as buying a put to protect shares you hold.", hi: "ऐसी पोज़िशन लेना जो दूसरी के जोखिम की भरपाई करे, जैसे अपने शेयरों की सुरक्षा के लिए पुट ख़रीदना।" } },
 { cat: "derivatives", term: { en: "Arbitrage", hi: "आर्बिट्राज" }, def: { en: "Profiting from a price difference for the same asset in two markets by buying in one and selling in the other.", hi: "एक ही एसेट की दो बाज़ारों की कीमत के अंतर से लाभ, एक में ख़रीदकर और दूसरे में बेचकर।" } },
 { cat: "derivatives", term: { en: "Underlying asset", hi: "अंतर्निहित एसेट" }, def: { en: "The share, index, commodity or currency on which a derivative contract is based.", hi: "वह शेयर, इंडेक्स, कमोडिटी या मुद्रा जिस पर डेरिवेटिव अनुबंध आधारित होता है।" } },
 { cat: "derivatives", term: { en: "Mark to market", hi: "मार्क टू मार्केट (MTM)" }, def: { en: "Valuing open positions at each day's closing price and settling the gain or loss in your account daily.", hi: "खुली पोज़िशन का हर दिन की क्लोज़िंग कीमत पर मूल्यांकन और लाभ-हानि का रोज़ खाते में निपटान।" } },
 { cat: "derivatives", term: { en: "Cost of carry", hi: "कॉस्ट ऑफ़ कैरी" }, def: { en: "The financing cost of holding an asset until a future date, minus any income from it. It links futures prices to spot prices.", hi: "भविष्य की तारीख़ तक एसेट रखने की वित्त लागत, घटा उससे होने वाली आय। यह फ़्यूचर्स कीमत को स्पॉट कीमत से जोड़ती है।" } },
 { cat: "derivatives", term: { en: "Black-Scholes model", hi: "ब्लैक-शोल्स मॉडल" }, def: { en: "A widely taught formula that prices options from the spot price, strike, time, interest rate and volatility.", hi: "स्पॉट कीमत, स्ट्राइक, समय, ब्याज दर और अस्थिरता से ऑप्शन की कीमत निकालने वाला प्रचलित सूत्र।" } },
 { cat: "derivatives", term: { en: "Put-call ratio (PCR)", hi: "पुट-कॉल अनुपात (PCR)" }, def: { en: "Put open interest divided by call open interest, watched as a rough gauge of market sentiment.", hi: "पुट ओपन इंटरेस्ट ÷ कॉल ओपन इंटरेस्ट, जिसे बाज़ार के मूड का मोटा पैमाना माना जाता है।" } },
 { cat: "derivatives", term: { en: "Credit default swap (CDS)", hi: "क्रेडिट डिफ़ॉल्ट स्वैप (CDS)" }, def: { en: "A contract in which one party pays a fee and is compensated if a specified borrower defaults, which works like insurance on debt.", hi: "अनुबंध जिसमें एक पक्ष शुल्क देता है और तय कर्ज़दार के डिफ़ॉल्ट करने पर मुआवज़ा पाता है; यह कर्ज़ के बीमा जैसा है।" } }
);
